sp_CriarFornecedor	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_CriarFornecedor`(\n\n    p_idEmpresa   INT,\n\n    p_NomeFantasia VARCHAR(120),\n\n    p_RazaoSocial  VARCHAR(120),\n\n    p_CNPJ         VARCHAR(14),\n\n    p_Telefone     VARCHAR(11),\n\n    p_Email        VARCHAR(80)\n\n)\nBEGIN\n\n    INSERT INTO Fornecedor (NomeFantasia, RazaoSocial, CNPJ, Telefone, Email, fAtivo, idEmpresa)\n\n    VALUES (p_NomeFantasia, p_RazaoSocial, p_CNPJ, p_Telefone, p_Email, 1, p_idEmpresa);\n\n\n\n    SELECT LAST_INSERT_ID() AS idFornecedor;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
